window.__rgjG=null; window.__rgjErr=null;
(async () => { try {
  const relay = (req) => new Promise(res => {
    const id = 'p' + Math.random().toString(36).slice(2);
    const t = setTimeout(() => { window.removeEventListener('message', h); res({ ok:false, status:0, text:'relay timeout' }); }, 9000);
    function h(ev) { const d = ev.data; if (!d || d.__rgjLan !== 1 || d.id !== id || !d.res) return;
      clearTimeout(t); window.removeEventListener('message', h); res(d.res); }
    window.addEventListener('message', h);
    window.postMessage({ __rgjLan: 1, id, req }, location.origin);
  });
  const base = 'http://192.168.1.169';
  const out = { steps: [] };
  const login = await relay({ method:'POST', url: base + '/api/login', headers:{'Content-Type':'application/json'},
                              body: JSON.stringify({ username:'ark', password:'ark' }) });
  out.steps.push(['login', login.status, String(login.text).slice(0,80)]);
  const tok = String(login.text||'').replace(/^"|"$/g,'').trim();
  if (!login.ok) { window.__rgjG = JSON.stringify(out); return; }
  const H = { 'X-Auth': tok };
  const ls = await relay({ method:'GET', url: base + '/api/resources/?override=true', headers: H });
  out.steps.push(['root', ls.status, String(ls.text).slice(0,300)]);
  const mk = await relay({ method:'GET', url: base + '/api/resources/rgj?override=true', headers: H });
  out.steps.push(['rgj', mk.status, String(mk.text).slice(0,300)]);
  const dev = await relay({ method:'GET', url: base + '/api/raw/rgj-device.json', headers: H });
  out.steps.push(['marker', dev.status, String(dev.text).slice(0,300)]);
  const q = await relay({ method:'GET', url: base + '/api/raw/rgj%2Frgj-queue.jsonl', headers: H });
  out.steps.push(['queue', q.status, String(q.text).slice(0,300)]);
  window.__rgjG = JSON.stringify(out);
} catch(e) { window.__rgjErr = String(e && e.stack || e); } })();
